const REQUIRED: Record<Route['allowedFor'], string> = {
  serve: LOYALTY_SERVE,
  accounts: LOYALTY_ACCOUNTS_VIEW,
  adjust: LOYALTY_ADJUST,
  programmeRead: 'loyalty:view',
  programmeWrite: 'rewards:manage',
  feedback: 'feedback:view',
  messagesView: 'messages:view',
  messagesSend: 'messages:send',
};

function call(
  user: string | null,
  method: string,
  path: string,
  body: unknown,
  business = 'business-a',
  branch?: string,
) {
  return app.request(
    path,
    {
      method,
      headers: {
        ...(user ? { 'x-test-user': user } : {}),
        'X-Business-Id': business,
        ...(branch ? { 'X-Branch-Id': branch } : {}),
        'Content-Type': 'application/json',
      },
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    },
    {} as Bindings,
    { waitUntil: vi.fn(), passThroughOnException: vi.fn() } as unknown as ExecutionContext,
  );
}
async function code(res: Response) {
  return ((await res.json()) as { error?: { code?: string } }).error?.code;
}
const passedPermissionLayer = (status: number) => status !== 401 && status !== 403;

let personas: Record<string, string[]>;
beforeEach(async () => {
  vi.clearAllMocks();
  personas = await defaultRoleGrants();
  mocks.membership.mockImplementation(async (_u: string, business: string) =>
    business === 'business-a' ? [{ branchId: null }] : [],
  );
});

describe('default role grants (real RoleProvisioningService)', () => {
  it('Staff is exactly the cashier set and holds none of the legacy exposure', () => {
    expect([...(personas.Staff ?? [])].sort()).toEqual([...STAFF_DEFAULT].sort());
    for (const key of [
      ...LEGACY_STAFF_EXPOSURE,
      LOYALTY_ACCOUNTS_VIEW,
      LOYALTY_ADJUST,
      'rewards:manage',
      'feedback:manage',
      'analytics:view',
      'billing:view',
      'team:view',
    ]) {
      expect(personas.Staff, key).not.toContain(key);
    }
  });
  it('Owner, Admin and Manager receive all three new permissions and keep their authority', () => {
    for (const role of ['Owner', 'Admin', 'Manager']) {
      for (const key of [
        LOYALTY_SERVE,
        LOYALTY_ACCOUNTS_VIEW,
        LOYALTY_ADJUST,
        'rewards:manage',
        'loyalty:view',
      ])
        expect(personas[role], `${role} ${key}`).toContain(key);
    }
  });
  it('Manager gets no billing:manage or business:delete; Admin gets no billing:manage', () => {
    expect(personas.Manager).not.toContain('billing:manage');
    expect(personas.Manager).not.toContain('business:delete');
    expect(personas.Admin).not.toContain('billing:manage');
  });
  it('the historical Staff default is documented evidence, not the current default', () => {
    expect(HISTORICAL_STAFF_DEFAULT).toContain('loyalty:manage');
    expect(STAFF_DEFAULT).not.toContain('loyalty:manage');
  });
});

describe('route-to-permission matrix', () => {
  for (const persona of ['Staff', 'Manager', 'Admin', 'Owner']) {
    describe(persona, () => {
      for (const route of ROUTES) {
        it(`${route.label}: ${route.method} ${route.path}`, async () => {
          mocks.permissions.mockResolvedValue(new Set(personas[persona]));
          const res = await call('user-1', route.method, route.path, route.body);
          const holds = personas[persona]!.includes(REQUIRED[route.allowedFor]);
          if (holds) {
            expect(passedPermissionLayer(res.status), `status ${res.status}`).toBe(true);
          } else {
            expect(res.status).toBe(403);
            expect(await code(res)).toBe('PERMISSION_DENIED');
          }
        });
      }
    });
  }

  it('default Staff can serve and cannot administer (explicit summary of acceptance tests 1-8)', async () => {
    mocks.permissions.mockResolvedValue(new Set(personas.Staff));
    const allowed = ROUTES.filter((r) => r.allowedFor === 'serve');
    const denied = ROUTES.filter((r) => r.allowedFor !== 'serve');
    for (const r of allowed)
      expect(
        passedPermissionLayer((await call('s', r.method, r.path, r.body)).status),
        r.label,
      ).toBe(true);
    for (const r of denied)
      expect((await call('s', r.method, r.path, r.body)).status, r.label).toBe(403);
  });

  it('a Staff role that was never reconciled (legacy grants only) is denied service and administration: fails closed', async () => {
    mocks.permissions.mockResolvedValue(new Set(HISTORICAL_STAFF_DEFAULT));
    for (const r of ROUTES.filter(
      (x) => x.allowedFor === 'serve' || x.allowedFor === 'accounts' || x.allowedFor === 'adjust',
    )) {
      expect((await call('s', r.method, r.path, r.body)).status, r.label).toBe(403);
    }
  });

  it('legacy loyalty:manage alone cannot adjust, serve or list accounts', async () => {
    mocks.permissions.mockResolvedValue(new Set(['loyalty:manage', 'loyalty:view']));
    for (const label of [
      'manual adjustment',
      'record purchase',
      'resolve QR',
      'account directory',
    ]) {
      const r = ROUTES.find((x) => x.label === label)!;
      expect((await call('s', r.method, r.path, r.body)).status, label).toBe(403);
    }
  });
});

describe('tenant, branch, session and failure behaviour', () => {
  it('unauthenticated requests are denied on every route', async () => {
    for (const r of ROUTES)
      expect((await call(null, r.method, r.path, r.body)).status, r.label).toBe(401);
    expect(mocks.reached).not.toHaveBeenCalled();
  });

  it('cross-tenant: a member of business A is denied on business B for every route', async () => {
    mocks.permissions.mockResolvedValue(new Set(personas.Owner));
    for (const r of ROUTES) {
      const res = await call('owner', r.method, r.path, r.body, 'business-b');
      expect(res.status, r.label).toBe(403);
      expect(await code(res), r.label).toBe('NOT_A_MEMBER');
    }
  });

  it('cross-branch: a branch-scoped user cannot select another branch', async () => {
    mocks.membership.mockResolvedValue([{ branchId: 'branch-a' }]);
    mocks.permissions.mockResolvedValue(new Set(personas.Staff));
    const res = await call(
      's',
      'POST',
      '/loyalty/actions/resolve-customer',
      { customerQrToken: 't' },
      'business-a',
      'branch-b',
    );
    expect(res.status).toBe(403);
    expect(await code(res)).toBe('BRANCH_ACCESS_DENIED');
  });

  it('branch-scoped users cannot use business-wide administrative routes even with the permission', async () => {
    mocks.membership.mockResolvedValue([{ branchId: 'branch-a' }]);
    mocks.permissions.mockResolvedValue(new Set(personas.Manager));
    for (const label of ['account directory', 'manual adjustment', 'tiers read']) {
      const r = ROUTES.find((x) => x.label === label)!;
      expect(
        (await call('m', r.method, r.path, r.body, 'business-a', 'branch-a')).status,
        label,
      ).toBe(403);
    }
  });

  it('a failed permission lookup denies sensitive operations and never reaches business logic', async () => {
    mocks.permissions.mockRejectedValue(new Error('database unavailable'));
    for (const label of [
      'manual adjustment',
      'account directory',
      'record purchase',
      'feedback list',
      'conversation list',
    ]) {
      const r = ROUTES.find((x) => x.label === label)!;
      const res = await call('o', r.method, r.path, r.body);
      expect(res.status, label).toBeGreaterThanOrEqual(400);
      expect([200, 201]).not.toContain(res.status);
    }
    expect(mocks.reached).not.toHaveBeenCalled();
  });

  it('denied requests never reach business logic', async () => {
    mocks.permissions.mockResolvedValue(new Set(personas.Staff));
    for (const r of ROUTES.filter((x) => x.allowedFor !== 'serve'))
      await call('s', r.method, r.path, r.body);
    expect(mocks.reached).not.toHaveBeenCalled();
  });
});

describe('no customer-directory or enumeration route exists', () => {
  it('loyalty GET routes are exactly the reviewed list (adding one needs a deliberate decision, D-C2)', () => {
    const gets = [
      ...new Set(
        (loyaltyRoutes as unknown as { routes: { method: string; path: string }[] }).routes
          .filter((r) => r.method === 'GET' && !r.path.includes('*'))
          .map((r) => r.path),
      ),
    ].sort();
    expect(gets).toEqual(
      [
        '/accounts',
        '/accounts/:id',
        '/accounts/:id/transactions',
        '/redemptions/:code',
        '/rewards',
        '/rewards/:id/dashboard',
        '/settings',
        '/tiers',
      ].sort(),
    );
    for (const path of gets) expect(path).not.toMatch(/search|phone|name|lookup|customers/i);
  });
});
